xcrun swift - <<'SWIFT'
import Cocoa
import ApplicationServices

let system = AXUIElementCreateSystemWide()
var focused: AnyObject?
let err = AXUIElementCopyAttributeValue(system, kAXFocusedApplicationAttribute as CFString, &focused)
guard err == .success, let app = focused else { exit(1) }
let appEl = app as! AXUIElement
var windows: AnyObject?
if AXUIElementCopyAttributeValue(appEl, kAXWindowsAttribute as CFString, &windows) != .success { exit(2) }
if let wins = windows as? [AXUIElement] {
    for win in wins {
        var title: AnyObject?
        _ = AXUIElementCopyAttributeValue(win, kAXTitleAttribute as CFString, &title)
        var roles: AnyObject?
        _ = AXUIElementCopyAttributeValue(win, kAXRoleAttribute as CFString, &roles)
        if let t = title as? String { print("window:", t) }
        var buttons: AnyObject?
        if AXUIElementCopyAttributeValue(win, kAXChildrenAttribute as CFString, &buttons) == .success,
           let children = buttons as? [AXUIElement] {
            for child in children {
                var role: AnyObject?
                _ = AXUIElementCopyAttributeValue(child, kAXRoleAttribute as CFString, &role)
                var title: AnyObject?
                _ = AXUIElementCopyAttributeValue(child, kAXTitleAttribute as CFString, &title)
                if let r = role as? String, r == kAXButtonRole as String, let tt = title as? String {
                    print("button:", tt)
                    if tt == "Open" {
                        _ = AXUIElementPerformAction(child, kAXPressAction as CFString)
                        exit(0)
                    }
                }
            }
        }
    }
}
exit(3)
SWIFT
